using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluationChatClient = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();
        await _appHost.StartAsync();

        _chatClient = _appHost.Application.Services.GetRequiredService<IChatClient>();
        _evaluationChatClient = _appHost.Application.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_responds_coherently()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.IsFalse(string.IsNullOrWhiteSpace(responseText), "Response should not be empty.");

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
        };

        var chatConfiguration = new ChatConfiguration(_evaluationChatClient);
        var results = await EvaluateAsync(evaluators, chatConfiguration, messages, response);

        foreach (var result in results)
        {
            Assert.IsTrue(
                result.Value.Rating >= EvaluationRating.Average,
                $"Evaluator '{result.Key}' rated response below average: {result.Value.Rating}");
        }
    }

    [TestMethod]
    public async Task Chat_responds_to_follow_up()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about .NET Aspire in one sentence."),
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.IsFalse(string.IsNullOrWhiteSpace(responseText), "Response should not be empty.");

        messages.Add(new ChatMessage(ChatRole.Assistant, responseText));
        messages.Add(new ChatMessage(ChatRole.User, "Can you elaborate on its key benefits?"));

        var followUp = await _chatClient.GetResponseAsync(messages);
        var followUpText = followUp.Text ?? string.Empty;

        Assert.IsFalse(string.IsNullOrWhiteSpace(followUpText), "Follow-up response should not be empty.");

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
        };

        var chatConfiguration = new ChatConfiguration(_evaluationChatClient);
        var results = await EvaluateAsync(evaluators, chatConfiguration, messages, followUp);

        foreach (var result in results)
        {
            Assert.IsTrue(
                result.Value.Rating >= EvaluationRating.Average,
                $"Evaluator '{result.Key}' rated follow-up below average: {result.Value.Rating}");
        }
    }

    [TestMethod]
    public async Task Chat_handles_grounding()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Based on the following context, answer the question.\n\nContext: The Eiffel Tower is 330 meters tall and located in Paris.\n\nQuestion: How tall is the Eiffel Tower?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.IsFalse(string.IsNullOrWhiteSpace(responseText), "Response should not be empty.");

        var evaluators = new IEvaluator[]
        {
            new GroundednessEvaluator(),
            new RelevanceEvaluator(),
        };

        var chatConfiguration = new ChatConfiguration(_evaluationChatClient);
        var results = await EvaluateAsync(evaluators, chatConfiguration, messages, response);

        foreach (var result in results)
        {
            Assert.IsTrue(
                result.Value.Rating >= EvaluationRating.Good,
                $"Evaluator '{result.Key}' rated grounded response below good: {result.Value.Rating}");
        }
    }

    private static async Task<Dictionary<string, EvaluationResult>> EvaluateAsync(
        IEvaluator[] evaluators,
        ChatConfiguration chatConfiguration,
        IList<ChatMessage> messages,
        ChatResponse response)
    {
        var results = new Dictionary<string, EvaluationResult>();
        var turnContext = new TurnContext(messages, response);

        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(turnContext, chatConfiguration);
            results[evaluator.GetType().Name] = result;
        }

        return results;
    }
}

