        AssertAllMetricsAtLeast(result, EvaluationRating.Average);
    }

    [TestMethod]
    public async Task Chat_responds_to_follow_up()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about .NET Aspire in one sentence.")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.IsFalse(
            string.IsNullOrWhiteSpace(response.Text),
            "Response should not be empty.");

        messages.Add(new ChatMessage(ChatRole.Assistant, response.Text));
        messages.Add(new ChatMessage(ChatRole.User, "Can you elaborate on its key benefits?"));

        var followUp = await _chatClient.GetResponseAsync(messages);

        Assert.IsFalse(
            string.IsNullOrWhiteSpace(followUp.Text),
            "Follow-up response should not be empty.");

        var chatConfiguration = new ChatConfiguration(_chatClient);
        var evaluator = new CompositeEvaluator(
            new CoherenceEvaluator(),
            new RelevanceEvaluator());

        var result = await evaluator.EvaluateAsync(messages, followUp, chatConfiguration);

        AssertAllMetricsAtLeast(result, EvaluationRating.Average);
    }

    [TestMethod]
    public async Task Chat_handles_grounding()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User,
                "Based on the following context, answer the question.\n\n" +
                "Context: The Eiffel Tower is 330 meters tall and located in Paris.\n\n" +
                "Question: How tall is the Eiffel Tower?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.IsFalse(
            string.IsNullOrWhiteSpace(response.Text),
            "Response should not be empty.");

        var chatConfiguration = new ChatConfiguration(_chatClient);
        var groundingContext = new GroundednessEvaluatorContext(
            "The Eiffel Tower is 330 meters tall and located in Paris.");

        var evaluator = new CompositeEvaluator(
            new GroundednessEvaluator(),
            new RelevanceEvaluator());

        var result = await evaluator.EvaluateAsync(
            messages, response, chatConfiguration, [groundingContext]);

        AssertAllMetricsAtLeast(result, EvaluationRating.Good);
    }

    [TestMethod]
    public async Task Chat_completeness()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "List three benefits of cloud computing.")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.IsFalse(
            string.IsNullOrWhiteSpace(response.Text),
            "Response should not be empty.");

        var chatConfiguration = new ChatConfiguration(_chatClient);
        var completenessContext = new CompletenessEvaluatorContext(
            "Cloud computing provides scalability, cost savings, and flexibility.");

        var evaluator = new CompositeEvaluator(
            new CompletenessEvaluator(),
            new FluencyEvaluator());

        var result = await evaluator.EvaluateAsync(
            messages, response, chatConfiguration, [completenessContext]);

        AssertAllMetricsAtLeast(result, EvaluationRating.Average);
    }

    private static void AssertAllMetricsAtLeast(EvaluationResult result, EvaluationRating minimum)
    {
        foreach (var (name, metric) in result)
        {
            var rating = metric.Interpretation?.Rating ?? EvaluationRating.Unknown;
            Assert.IsTrue(
                rating >= minimum,
                $"Metric '{name}' rated {rating}, expected at least {minimum}.");
        }
    }
}

