         AssertAllMetricsAtLeast(result, EvaluationRating.Average);
     }

     private static void AssertAllMetricsAtLeast(EvaluationResult result, EvaluationRating minimum)
     {
         foreach (var (name, metric) in result.Metrics)
         {
             var rating = metric.Interpretation?.Rating ?? EvaluationRating.Unknown;
             Assert.IsTrue(
                 rating >= minimum,
                 $"Metric '{name}' rated {rating}, expected at least {minimum}.");
         }
     }
 }

